"""NEW CAD: an atlas of unimodular views of structural division witnesses.

Inspired by Div_Zero.md: ratio presentation, reciprocal rho, quarter-turn J,
shear T_q, Euclid traces. This atlas is our NEW DESIGN, not from the source.
Views DO NOT mutate the exceptional 0/0 carrier and DO NOT turn a witness
into an ordinary arithmetic value. They read the (a,b) witness in several
coordinate charts using invertible matrices in GL(2,Z).
"""
from dataclasses import dataclass
from math import atan2, pi, gcd
from typing import Tuple
import numpy as np

Mat = Tuple[int,int,int,int]
def det(m:Mat)->int:return m[0]*m[3]-m[1]*m[2]
def mm(a:Mat,b:Mat)->Mat:
    return (a[0]*b[0]+a[1]*b[2],a[0]*b[1]+a[1]*b[3],a[2]*b[0]+a[3]*b[2],a[2]*b[1]+a[3]*b[3])
I=(1,0,0,1);RHO=(0,1,1,0);J=(0,-1,1,0)
def shear(k):return (1,k,0,1)

def chart_atlas():
    """Small fixed atlas generated by shear, reciprocal and J."""
    # Deliberately include both unimodular sign orientations.
    generators=[I,RHO,J,mm(J,J),mm(J,mm(J,J))]
    for k in (-3,-2,-1,1,2,3):
        generators.extend((shear(k),mm(RHO,shear(k)),mm(J,shear(k)),mm(shear(k),RHO)))
    unique=[]
    for m in generators:
        if m not in unique:
            assert abs(det(m))==1
            unique.append(m)
    return tuple(unique)

CHARTS=chart_atlas()

def euclid_trace(a:int,b:int,max_steps=100):
    aa,bb=abs(int(a)),abs(int(b)); trace=[]
    for _ in range(max_steps):
        if bb==0:break
        q,r=divmod(aa,bb);trace.append(q);aa,bb=bb,r
    return tuple(trace), aa

@dataclass(frozen=True)
class Projection:
    view:int
    matrix:Mat
    a:int
    b:int
    quantile:float
    signature:tuple
    quotients:tuple
    gcd:int


def project(witness,view:int) -> Projection:
    if not witness.verify():raise ValueError('Not a zero-division witness')
    m=CHARTS[view]
    a,b=witness.direction
    x=m[0]*a+m[1]*b;y=m[2]*a+m[3]*b
    cf,g=euclid_trace(x,y)
    # 0/0 exceptional direction: a=b=0 admits no projective direction.
    # Deterministic fallback is stored explicitly, not silently normalized.
    theta=atan2(y,x) if x or y else 0.0
    # Phase readout of projective chart; maps each signed quadrant to [0,1).
    u=(theta/(pi/2.0))%1.0
    u=min(max(u,1e-12),1-1e-12)
    # Features of the Euclid quotient path and view of the original witness.
    # NOT claimed to be complete topological invariants of 0/0.
    sg=(0 if x==0 else (1 if x>0 else -1),0 if y==0 else (1 if y>0 else -1))
    sig=(min(len(cf),6),sum(int(v)&1 for v in cf)%3,
         min(g,3),sg[0],sg[1],
         min(int(u*8),7))
    return Projection(view,m,x,y,u,sig,cf,g)


def sanity_check():
    for m in CHARTS:assert abs(det(m))==1
    for x,y in [(0,0),(0,1),(1,0),(15,23),(128,64)]:
        for m in CHARTS:
            a=m[0]*x+m[1]*y;b=m[2]*x+m[3]*y
            assert gcd(abs(a),abs(b))==gcd(x,y)
    return len(CHARTS)
